 "terms": {
  "intuition": {
   "en": "intuition & personal experience",
   "zh": "個人直覺與經驗",
   "def": "「我以前也是這樣，所以他一定也是。」只用自己的感覺和經驗下判斷，沒有去查證。 Judging from your own feelings and past, without checking."
  },
  "authority": {
   "en": "authority",
   "zh": "權威人士的說法",
   "def": "因為說話的人有地位（里長、老師、專家），就相信他說的是對的。 Believing something because of who says it."
  },
  "tradition": {
   "en": "tradition",
   "zh": "傳統與前例",
   "def": "「我們一直都是這樣做的。」照過去的做法，卻沒有檢查它有沒有用。 Doing it the old way without checking whether it works."
  },
  "common_sense": {
   "en": "common sense",
   "zh": "一般常識",
   "def": "「大家都知道……」聽起來很合理，但不一定是真的。 What \"everyone knows\" can be wrong."
  },
  "logic": {
   "en": "logic (reasoning)",
   "zh": "邏輯推理",
   "def": "推理的形式正確，但如果前提沒有查證，結論還是會錯。 Correct reasoning from an unchecked premise still gives a wrong answer."
  },
  "halo": {
   "en": "halo effect",
   "zh": "月暈效應",
   "def": "因為一個人某方面很好（籃球、外表、名氣），就以為他每一方面都很好。 Good at one thing ≠ good at everything."
  },
  "empirical": {
   "en": "empirical research",
   "zh": "實證研究",
   "def": "有系統地蒐集資料、分析資料，用證據來回答問題。 Answering questions by collecting and analyzing data."
  },
  "purposes": {
   "en": "five purposes of research",
   "zh": "研究的五個目的",
   "def": "敘述（發生什麼？）、解釋（為什麼？）、預測（會怎樣？）、介入與處遇（該怎麼做？）、比較與評估（有效嗎？）。 Describe, explain, predict, intervene, evaluate."
  },
  "quantitative": {
   "en": "quantitative research",
   "zh": "量化研究",
   "def": "用數字「算」：問卷、統計。適合描述多少人、比較、預測。 Counting: surveys and statistics."
  },
  "qualitative": {
   "en": "qualitative research",
   "zh": "質性研究",
   "def": "用文字「懂」：訪談、觀察，在自然的情境中了解人的經驗與意義。 Understanding: interviews and observation."
  },
  "deductive": {
   "en": "deductive logic",
   "zh": "演繹法",
   "def": "從理論或假設出發，再用資料檢驗（常見於量化研究）。 Theory → hypothesis → data."
  },
  "inductive": {
   "en": "inductive logic",
   "zh": "歸納法",
   "def": "從資料出發，慢慢找出模式，建立新的想法或理論（常見於質性研究）。 Data → patterns → new idea."
  },
  "research_question": {
   "en": "research question",
   "zh": "研究問題",
   "def": "研究要回答的問題。好的研究問題清楚、可以用資料回答、而且重要。 Clear, answerable, and important."
  },
  "hypothesis": {
   "en": "hypothesis",
   "zh": "研究假設",
   "def": "可以被資料檢驗的預測，常寫成「如果……，那麼……」。 A testable prediction: \"If…, then…\""
  },
  "six_steps": {
   "en": "six steps of research",
   "zh": "研究的六個步驟",
   "def": "選定研究問題 → 檢閱文獻 → 提出研究設計 → 蒐集資料 → 分析資料 → 撰寫研究報告。"
  },
  "lit_review": {
   "en": "literature review",
   "zh": "文獻探討",
   "def": "先查已經有哪些研究，並判斷來源可不可信（例如經過同儕審查的期刊），不要從零開始猜。 What do we already know?"
  },
  "informed_consent": {
   "en": "informed consent",
   "zh": "知情同意",
   "def": "研究前先說清楚目的、過程與風險；參與者了解後自願同意，也可以隨時退出。 People agree freely after they understand."
  },
  "confidentiality": {
   "en": "confidentiality",
   "zh": "保密",
   "def": "保護參與者的身分和資料，不公開可以認出他們的資訊。 Protect who said what."
  },
  "ebp": {
   "en": "evidence-based practice (EBP)",
   "zh": "實證為基礎的實務",
   "def": "結合三件事：最好的研究證據、社工的專業經驗、案主的價值與偏好。 Evidence + expertise + client values."
  },
  "needs_assessment": {
   "en": "needs assessment",
   "zh": "需求評量",
   "def": "在方案開始「之前」，先蒐集資料了解大家真正需要什麼。 Before the program: what do people need?"
  },
  "output_outcome": {
   "en": "output vs. outcome",
   "zh": "產出與成效",
   "def": "產出＝做了多少（辦了幾次課）；成效＝改變了多少（跌倒少了多少）。 How much we did vs. how much changed."
  },
  "comparison_group": {
   "en": "comparison group",
   "zh": "比較組",
   "def": "找一群相似、但沒有參加方案的人來比較，才比較能確定改變是方案造成的。 Compare with similar people who did not get the program."
  },
  "observation": {
   "en": "observation",
   "zh": "觀察法",
   "def": "照時間、有系統地記下實際看到的事，不靠猜測。紀錄就是資料。 Watching and recording what really happens."
  },
  "mixed_methods": {
   "en": "mixed methods",
   "zh": "混合研究方法",
   "def": "同時使用量化（問卷）和質性（訪談），既知道「多少」，也知道「為什麼」。 Counting and understanding together."
  }
 },
